let trigger = {};
try {
  const triggerItems = $('When Executed by Another Workflow').all();
  trigger = triggerItems.length ? triggerItems[0].json : {};
} catch (e) { trigger = {}; }
const asOfDate = trigger.asOfDate || new Date().toISOString().slice(0, 10);
const backfillAll = trigger.backfillAll === true;

return $input.all().map((item) => ({
  json: { ...item.json, asOfDate, backfillAll },
}));

/**
 * helpers.js
 *
 * Shared low-level utilities used by every other module in /code and by the
 * equivalent n8n Code nodes. Pure functions only — no I/O, no n8n APIs — so
 * this file can be unit tested with plain `node` and pasted into a Code node
 * body unchanged (just drop the `module.exports` line).
 *
 * Candle shape (normalized, provider-agnostic — see docs/DATA_PROVIDER.md):
 * {
 *   symbol: "COMI",
 *   date: "2026-08-18",     // ISO date, trading session date
 *   open: 100.20,
 *   high: 103.10,
 *   low: 99.80,
 *   close: 102.70,
 *   volume: 12500000,
 *   tradedValue: 1270000000 // optional, derived if absent
 * }
 */

/** Returns true if v is a finite, non-NaN number. */
function isNumber(v) {
  return typeof v === "number" && Number.isFinite(v);
}

/** Safe division: returns null instead of Infinity/NaN when denominator is unusable. */
function safeDivide(numerator, denominator) {
  if (!isNumber(numerator) || !isNumber(denominator) || denominator === 0) {
    return null;
  }
  const result = numerator / denominator;
  return Number.isFinite(result) ? result : null;
}

/** Rounds to `decimals` places, returns null for non-numeric input. */
function round(value, decimals = 4) {
  if (!isNumber(value)) return null;
  const factor = Math.pow(10, decimals);
  return Math.round(value * factor) / factor;
}

/** Percentage change from `from` to `to`. Returns null if from <= 0 or invalid. */
function pctChange(from, to) {
  if (!isNumber(from) || !isNumber(to) || from === 0) return null;
  return ((to - from) / from) * 100;
}

/**
 * Validates a single raw candle. Returns { valid, errors[] }.
 * Mirrors the rules in spec section 31.
 */
function validateCandle(candle) {
  const errors = [];
  if (!candle || typeof candle !== "object") {
    return { valid: false, errors: ["candle is not an object"] };
  }
  const { symbol, date, open, high, low, close, volume } = candle;

  if (!symbol || typeof symbol !== "string") errors.push("missing/invalid symbol");
  if (!date || Number.isNaN(Date.parse(date))) errors.push("missing/invalid date");
  if (!isNumber(open)) errors.push("open is not numeric");
  if (!isNumber(high)) errors.push("high is not numeric");
  if (!isNumber(low)) errors.push("low is not numeric");
  if (!isNumber(close)) errors.push("close is not numeric");
  if (!isNumber(volume)) errors.push("volume is not numeric");

  if (isNumber(open) && isNumber(high) && isNumber(low) && isNumber(close)) {
    if (high < open) errors.push("high < open");
    if (high < close) errors.push("high < close");
    if (high < low) errors.push("high < low");
    if (low > open) errors.push("low > open");
    if (low > close) errors.push("low > close");
  }
  if (isNumber(volume) && volume < 0) errors.push("negative volume");
  if (isNumber(close) && close <= 0) errors.push("close <= 0");

  return { valid: errors.length === 0, errors };
}

/**
 * Filters an array of raw candles into { valid[], invalid[] }.
 * `invalid` entries carry the original candle plus `.errors`.
 * Zero-volume candles are valid but flagged with a warning for downstream
 * consumers (suspicious, not necessarily wrong — EGX thin names do trade zero
 * volume on quiet sessions).
 */
function validateCandles(candles) {
  const valid = [];
  const invalid = [];
  for (const candle of candles || []) {
    const { valid: ok, errors } = validateCandle(candle);
    if (ok) {
      valid.push({ ...candle, suspiciousZeroVolume: candle.volume === 0 });
    } else {
      invalid.push({ ...candle, errors });
    }
  }
  return { valid, invalid };
}

/**
 * Removes duplicate candles (same symbol+date), keeping the last occurrence
 * (assumed most recent fetch / most authoritative).
 */
function dedupeCandles(candles) {
  const map = new Map();
  for (const c of candles || []) {
    map.set(`${c.symbol}::${c.date}`, c);
  }
  return Array.from(map.values());
}

/** Sorts candles ascending by date (oldest first) — mandatory before any TA calc. */
function sortCandlesAscending(candles) {
  return [...(candles || [])].sort((a, b) => new Date(a.date) - new Date(b.date));
}

/**
 * Derives tradedValue when the provider doesn't supply it directly.
 * Uses the session's typical price (H+L+C)/3 * volume as a reasonable proxy.
 */
function deriveTradedValue(candle) {
  if (isNumber(candle.tradedValue)) return candle.tradedValue;
  if (!isNumber(candle.high) || !isNumber(candle.low) || !isNumber(candle.close) || !isNumber(candle.volume)) {
    return null;
  }
  const typicalPrice = (candle.high + candle.low + candle.close) / 3;
  return typicalPrice * candle.volume;
}

/** Simple mean of the last `n` numeric values in `arr` (nulls skipped). Returns null if insufficient data. */
function meanOfLast(arr, n) {
  if (!Array.isArray(arr) || arr.length < n) return null;
  const slice = arr.slice(-n).filter(isNumber);
  if (slice.length < n) return null;
  return slice.reduce((a, b) => a + b, 0) / n;
}

/** Standard deviation of the last `n` numeric values. Returns null if insufficient data. */
function stdDevOfLast(arr, n) {
  const mean = meanOfLast(arr, n);
  if (mean === null) return null;
  const slice = arr.slice(-n);
  const variance = slice.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / n;
  return Math.sqrt(variance);
}

/** Clamps a number into [min, max]. */
function clamp(value, min, max) {
  if (!isNumber(value)) return min;
  return Math.min(Math.max(value, min), max);
}

/**
 * Wraps arbitrary rows into n8n's expected item structure: [{ json: {...} }].
 * Accepts a single object or array of objects.
 */
function toN8nItems(rows) {
  const list = Array.isArray(rows) ? rows : [rows];
  return list.map((json) => ({ json }));
}

/**
 * Reads all `json` payloads out of an n8n items array back into plain objects.
 */
function fromN8nItems(items) {
  return (items || []).map((item) => item.json);
}

// ---------------------------------------------------------------------

/**
 * Ichimoku Kinko Hyo — context/display indicator (NOT a ranking input).
 *
 * Pure functions over an ascending candle array; no I/O, no n8n globals.
 * Embedded into the "Calculate Indicators" Code node of
 * workflows/04-egx-technical-analysis.json after helpers.js (drop the
 * `require` line and the `module.exports` block when pasting).
 *
 * Standard settings (9 / 26 / 52, displacement 26):
 *   tenkan  = (highest high + lowest low) / 2 over the last 9 bars
 *   kijun   = same over 26 bars
 *   senkouA = (tenkan + kijun) / 2, plotted 26 bars AHEAD
 *   senkouB = (highest high + lowest low) / 2 over 52 bars, plotted 26 ahead
 *
 * Because span A/B are plotted forward, the cloud that applies to bar i was
 * computed from bar i - 26. Every value returned here for index i is the one
 * a chart shows AT bar i, so nothing uses information after bar i (no
 * look-ahead). The chikou span (close shifted back) is deliberately not
 * stored — it is the same information as `close > close[i-26]`, which feeds
 * the signal below instead.
 *
 * Needs senkouB + displacement = 78 bars before the cloud exists; values are
 * null until then and the signal reads NEUTRAL.
 */


const DEFAULT_ICHIMOKU_SETTINGS = Object.freeze({
  tenkan: 9,
  kijun: 26,
  senkouB: 52,
  displacement: 26,
});

/** Midpoint of the highest high and lowest low over the trailing window. */
function midpointLine(candles, period) {
  const out = new Array(candles.length).fill(null);
  for (let i = period - 1; i < candles.length; i++) {
    let hi = -Infinity;
    let lo = Infinity;
    let valid = true;
    for (let j = i - period + 1; j <= i; j++) {
      const c = candles[j];
      if (!isNumber(c.high) || !isNumber(c.low)) { valid = false; break; }
      if (c.high > hi) hi = c.high;
      if (c.low < lo) lo = c.low;
    }
    out[i] = valid ? (hi + lo) / 2 : null;
  }
  return out;
}

/**
 * Signed distance from close to the nearest cloud edge, in % of close:
 *   > 0  close above the cloud top
 *   < 0  close below the cloud bottom
 *   0    close inside the cloud
 */
function cloudDistancePct(close, spanA, spanB) {
  if (!isNumber(close) || !isNumber(spanA) || !isNumber(spanB)) return null;
  const top = Math.max(spanA, spanB);
  const bottom = Math.min(spanA, spanB);
  if (close > top) return safeDivide(close - top, close) * 100;
  if (close < bottom) return safeDivide(close - bottom, close) * 100;
  return 0;
}

/**
 * Five-state read. Only price vs cloud decides bullish/bearish; the
 * tenkan/kijun cross and the 26-bar momentum (chikou proxy) upgrade it to
 * STRONG_*. Inside the cloud, or with too little history, it is NEUTRAL.
 */
function ichimokuSignal({ close, tenkan, kijun, spanA, spanB, closeBack }) {
  const dist = cloudDistancePct(close, spanA, spanB);
  if (!isNumber(dist)) return "NEUTRAL";
  if (dist === 0) return "NEUTRAL";
  const crossKnown = isNumber(tenkan) && isNumber(kijun);
  const momentumKnown = isNumber(closeBack);
  if (dist > 0) {
    return crossKnown && momentumKnown && tenkan > kijun && close > closeBack
      ? "STRONG_BULLISH" : "BULLISH";
  }
  return crossKnown && momentumKnown && tenkan < kijun && close < closeBack
    ? "STRONG_BEARISH" : "BEARISH";
}

/**
 * Returns arrays aligned with `candles` (ascending):
 * { tenkan, kijun, senkouA, senkouB, cloudDistPct, signal }
 * senkouA/senkouB[i] are the cloud values in force at bar i.
 */
function ichimoku(candles, settings = {}) {
  const s = { ...DEFAULT_ICHIMOKU_SETTINGS, ...settings };
  const n = Array.isArray(candles) ? candles.length : 0;
  const out = {
    tenkan: new Array(n).fill(null),
    kijun: new Array(n).fill(null),
    senkouA: new Array(n).fill(null),
    senkouB: new Array(n).fill(null),
    cloudDistPct: new Array(n).fill(null),
    signal: new Array(n).fill("NEUTRAL"),
  };
  if (n === 0) return out;

  const tenkan = midpointLine(candles, s.tenkan);
  const kijun = midpointLine(candles, s.kijun);
  const spanBRaw = midpointLine(candles, s.senkouB);

  for (let i = 0; i < n; i++) {
    const src = i - s.displacement; // bar whose spans are plotted at i
    const spanA = src >= 0 && isNumber(tenkan[src]) && isNumber(kijun[src])
      ? (tenkan[src] + kijun[src]) / 2 : null;
    const spanB = src >= 0 ? spanBRaw[src] : null;
    const close = candles[i].close;
    const closeBack = src >= 0 ? candles[src].close : null;

    out.tenkan[i] = round(tenkan[i], 6);
    out.kijun[i] = round(kijun[i], 6);
    out.senkouA[i] = round(spanA, 6);
    out.senkouB[i] = round(spanB, 6);
    out.cloudDistPct[i] = round(cloudDistancePct(close, spanA, spanB), 4);
    out.signal[i] = ichimokuSignal({ close, tenkan: tenkan[i], kijun: kijun[i], spanA, spanB, closeBack });
  }
  return out;
}

// ---------------------------------------------------------------------

/**
 * Price-discontinuity flag — a DATA-QUALITY tell, not a ranking input.
 *
 * Pure functions over an ascending candle array; no I/O, no n8n globals.
 * Embedded into the "Calculate Indicators" Code node of
 * workflows/04-egx-technical-analysis.json after helpers.js (drop the
 * `require` line and the `module.exports` block when pasting).
 *
 * Motivation (2026-09-06): the gap-through backfill in workflow 16 surfaced
 * outliers like an EGX stop "gapped" −99.6% and a US target "gapped" +378%.
 * Those are provider glitches of the SEIGA type (0.95 ↔ 228.51 prints), not
 * real gaps — and every rolling indicator (high252, ATR, Ichimoku spans,
 * drift/vol, S/R levels) computed across such a print is poisoned for up to
 * 252 sessions afterwards.
 *
 * Definition: bar i is a discontinuity when close[i] / close[i-1] is at least
 * `ratio` (default 3×) or at most 1/ratio. A single bad print therefore shows
 * up TWICE (the jump and the return). Genuine one-day moves of 3× do not
 * happen on EGX (±10–20% limits) and are extraordinary for the S&P-sized US
 * universe; an unadjusted split would also trip it, which is equally worth a
 * warning because the indicators are wrong across it either way.
 *
 * NOT folded into `data_confidence` — that column is a scoring input and the
 * two-slice walk-forward rule (docs/SCORING.md) applies to any ranking change.
 */


const DEFAULT_DISCONTINUITY_SETTINGS = Object.freeze({
  ratio: 3, // close/prevClose beyond 3× or below 1/3
  lookback: 252, // sessions the count covers (one trading year)
});

/**
 * Returns arrays aligned with `candles` (ascending):
 *   count[i]    number of discontinuities in the last `lookback` bars ending at i
 *   lastDate[i] date of the most recent one inside that window (null if none)
 *   lastPct[i]  its close-to-close change in % (e.g. +23954.7 for 0.95→228.51)
 */
function priceDiscontinuities(candles, settings = {}) {
  const cfg = { ...DEFAULT_DISCONTINUITY_SETTINGS, ...settings };
  const ratio = cfg.ratio > 1 ? cfg.ratio : DEFAULT_DISCONTINUITY_SETTINGS.ratio;
  const lookback = cfg.lookback > 0 ? cfg.lookback : DEFAULT_DISCONTINUITY_SETTINGS.lookback;
  const n = candles.length;

  const isBreak = new Array(n).fill(false);
  const jumpPct = new Array(n).fill(null);
  for (let i = 1; i < n; i++) {
    const prev = candles[i - 1].close;
    const cur = candles[i].close;
    if (!isNumber(prev) || !isNumber(cur) || prev <= 0 || cur <= 0) continue;
    const r = cur / prev;
    if (r >= ratio || r <= 1 / ratio) {
      isBreak[i] = true;
      jumpPct[i] = round((r - 1) * 100, 2);
    }
  }

  const count = new Array(n).fill(0);
  const lastDate = new Array(n).fill(null);
  const lastPct = new Array(n).fill(null);
  let running = 0;
  for (let i = 0; i < n; i++) {
    if (isBreak[i]) running += 1;
    if (i - lookback >= 0 && isBreak[i - lookback]) running -= 1;
    count[i] = running;
    if (running === 0) continue;
    if (isBreak[i]) {
      lastDate[i] = candles[i].date;
      lastPct[i] = jumpPct[i];
    } else {
      lastDate[i] = lastDate[i - 1];
      lastPct[i] = lastPct[i - 1];
    }
  }

  return { isBreak, count, lastDate, lastPct };
}

// ---------------------------------------------------------------------

/**
 * Smart Money Concepts (SMC) — context/display analysis (NOT a ranking input).
 *
 * Pure functions over an ascending candle array; no I/O, no n8n globals.
 * Embedded into the "Calculate Indicators" Code node of
 * workflows/04-egx-technical-analysis.json after helpers.js (drop the
 * `require` line and the `module.exports` block when pasting).
 *
 * What is computed, per bar, using only bars <= i (no look-ahead):
 *
 *   Swing points   fractal highs/lows with `swingLen` bars on each side. A
 *                  swing at bar j is only KNOWN at bar j + swingLen, so it is
 *                  registered there — never earlier.
 *   Structure      BULLISH after a close above the last unbroken swing high,
 *                  BEARISH after a close below the last unbroken swing low.
 *                  The break is a BOS (break of structure) when it continues
 *                  the current structure, a CHoCH (change of character) when
 *                  it flips it.
 *   Order blocks   the last opposite-colour candle before the move that broke
 *                  structure (bullish OB = last red candle before a BOS/CHoCH
 *                  up). Kept until price CLOSES through it (mitigated). One
 *                  active bullish and one active bearish OB are exposed.
 *   Fair value gaps three-candle imbalance: bullish when low[i] > high[i-2],
 *                  bearish when high[i] < low[i-2]. Unfilled until a later
 *                  bar trades through the whole gap; the nearest unfilled one
 *                  on each side of price is exposed.
 *   Liquidity sweep bar trades beyond the last swing high/low but closes back
 *                  inside it (stops taken, level held). SWEEP_HIGH is the
 *                  bearish grab above highs, SWEEP_LOW the bullish one.
 *   Range position close inside the dealing range [last swing low, last
 *                  swing high] in % (0 = at the low, 100 = at the high);
 *                  <= 50 is the "discount" half, > 50 the "premium" half.
 *   Bias           BULLISH_DISCOUNT / BULLISH_PREMIUM / BEARISH_PREMIUM /
 *                  BEARISH_DISCOUNT — structure + which half of the range the
 *                  close sits in. Null until a structure exists.
 *
 * None of this feeds overall_score, entry_quality or the /top-picks gate; it
 * is stored so the dashboard, the stock-detail drawer and the AI reviewer can
 * SEE it. Promoting any field to a ranking input needs the two-slice
 * walk-forward rule in docs/SCORING.md.
 */


const DEFAULT_SMC_SETTINGS = Object.freeze({
  swingLen: 3, // bars each side of a fractal swing
  obLookback: 20, // how far back to look for the order-block candle
  fvgMaxAge: 250, // drop unfilled gaps older than this many bars
  fvgMaxKeep: 40, // and never track more than this many per side
  sweepMemory: 20, // report a sweep for this many bars after it printed
});

/** True when bar j is a fractal high/low with `len` bars on both sides. */
function isSwing(candles, j, len, key, cmp) {
  const v = candles[j][key];
  if (!isNumber(v)) return false;
  for (let k = 1; k <= len; k++) {
    const l = candles[j - k][key];
    const r = candles[j + k][key];
    if (!isNumber(l) || !isNumber(r) || !cmp(v, l) || !cmp(v, r)) return false;
  }
  return true;
}

/** Last candle within `lookback` bars before `end` whose colour is `red` (close < open). */
function findOrderBlock(candles, end, lookback, red) {
  for (let j = end - 1; j >= Math.max(0, end - lookback); j--) {
    const c = candles[j];
    if (!isNumber(c.open) || !isNumber(c.close)) continue;
    if (red ? c.close < c.open : c.close > c.open) return { low: c.low, high: c.high, idx: j };
  }
  return null;
}

/** Nearest unfilled gap to `close` (by its edge facing price), or null. */
function nearestGap(gaps, close, edge) {
  let best = null;
  let bestDist = Infinity;
  for (const g of gaps) {
    const d = Math.abs(close - g[edge]);
    if (d < bestDist) {
      bestDist = d;
      best = g;
    }
  }
  return best;
}

/**
 * Returns an array aligned with `candles`; each element is the per-bar SMC
 * read (keys match the technical_analysis smc_* columns in camelCase).
 */
function smartMoney(candles, settings = {}) {
  const cfg = { ...DEFAULT_SMC_SETTINGS, ...settings };
  const L = cfg.swingLen;
  const n = candles.length;
  const out = new Array(n);

  let swingHigh = null; // { price, idx, broken }
  let swingLow = null;
  let structure = null;
  let lastEvent = null;
  let lastEventIdx = null;
  let bullOb = null;
  let bearOb = null;
  let bullGaps = [];
  let bearGaps = [];
  let lastSweep = null;
  let lastSweepIdx = null;

  for (let i = 0; i < n; i++) {
    const c = candles[i];
    const close = c.close;

    // 1. Register swings that became known at this bar (formed at i - L).
    const j = i - L;
    if (j >= L) {
      if (isSwing(candles, j, L, "high", (a, b) => a > b)) swingHigh = { price: candles[j].high, idx: j, broken: false };
      if (isSwing(candles, j, L, "low", (a, b) => a < b)) swingLow = { price: candles[j].low, idx: j, broken: false };
    }

    // 2. New fair value gaps printed by this bar.
    if (i >= 2 && isNumber(c.low) && isNumber(c.high)) {
      const h2 = candles[i - 2].high;
      const l2 = candles[i - 2].low;
      if (isNumber(h2) && c.low > h2) bullGaps.push({ low: h2, high: c.low, idx: i });
      if (isNumber(l2) && c.high < l2) bearGaps.push({ low: c.high, high: l2, idx: i });
    }

    if (isNumber(close) && isNumber(c.high) && isNumber(c.low)) {
      // 3. Structure breaks (on close) and liquidity sweeps (wick only).
      if (swingHigh && !swingHigh.broken) {
        if (close > swingHigh.price) {
          lastEvent = structure === "BEARISH" ? "CHOCH_UP" : "BOS_UP";
          lastEventIdx = i;
          structure = "BULLISH";
          swingHigh.broken = true;
          bullOb = findOrderBlock(candles, i, cfg.obLookback, true);
        } else if (c.high > swingHigh.price) {
          lastSweep = "SWEEP_HIGH";
          lastSweepIdx = i;
        }
      }
      if (swingLow && !swingLow.broken) {
        if (close < swingLow.price) {
          lastEvent = structure === "BULLISH" ? "CHOCH_DOWN" : "BOS_DOWN";
          lastEventIdx = i;
          structure = "BEARISH";
          swingLow.broken = true;
          bearOb = findOrderBlock(candles, i, cfg.obLookback, false);
        } else if (c.low < swingLow.price) {
          lastSweep = "SWEEP_LOW";
          lastSweepIdx = i;
        }
      }

      // 4. Mitigate order blocks and fill gaps with this bar's range.
      if (bullOb && close < bullOb.low) bullOb = null;
      if (bearOb && close > bearOb.high) bearOb = null;
      bullGaps = bullGaps.filter((g) => c.low > g.low && i - g.idx <= cfg.fvgMaxAge).slice(-cfg.fvgMaxKeep);
      bearGaps = bearGaps.filter((g) => c.high < g.high && i - g.idx <= cfg.fvgMaxAge).slice(-cfg.fvgMaxKeep);
    }

    // 5. Per-bar read.
    const fvgBull = isNumber(close) ? nearestGap(bullGaps, close, "high") : null;
    const fvgBear = isNumber(close) ? nearestGap(bearGaps, close, "low") : null;
    let rangePos = null;
    if (swingHigh && swingLow && isNumber(close) && swingHigh.price > swingLow.price) {
      rangePos = round(((close - swingLow.price) / (swingHigh.price - swingLow.price)) * 100, 2);
    }
    let bias = null;
    if (structure && isNumber(rangePos)) {
      const discount = rangePos <= 50;
      bias = structure === "BULLISH" ? (discount ? "BULLISH_DISCOUNT" : "BULLISH_PREMIUM") : discount ? "BEARISH_DISCOUNT" : "BEARISH_PREMIUM";
    }
    const sweepFresh = lastSweepIdx !== null && i - lastSweepIdx <= cfg.sweepMemory;

    out[i] = {
      smcStructure: structure,
      smcLastEvent: lastEvent,
      smcEventBarsAgo: lastEventIdx === null ? null : i - lastEventIdx,
      smcBullObLow: bullOb ? round(bullOb.low, 6) : null,
      smcBullObHigh: bullOb ? round(bullOb.high, 6) : null,
      smcBearObLow: bearOb ? round(bearOb.low, 6) : null,
      smcBearObHigh: bearOb ? round(bearOb.high, 6) : null,
      smcFvgBullLow: fvgBull ? round(fvgBull.low, 6) : null,
      smcFvgBullHigh: fvgBull ? round(fvgBull.high, 6) : null,
      smcFvgBearLow: fvgBear ? round(fvgBear.low, 6) : null,
      smcFvgBearHigh: fvgBear ? round(fvgBear.high, 6) : null,
      smcSweep: sweepFresh ? lastSweep : null,
      smcSweepBarsAgo: sweepFresh ? i - lastSweepIdx : null,
      smcRangePosPct: rangePos,
      smcBias: bias,
    };
  }

  return out;
}

// ---------------------------------------------------------------------

/**
 * contextIndicators.js
 *
 * Bundles the display-only context modules (Ichimoku, the price-discontinuity
 * flag, Smart Money Concepts) into one per-bar object so
 * indicators.calculateAllIndicators can spread them into the
 * technical_analysis row without growing past the 500-line cap.
 *
 * Everything here is context for the dashboard / stock-detail / AI reviewer.
 * Nothing feeds overall_score, entry_quality or the /top-picks gate — see the
